test('password sends the refresh grant to the refresh url and falls back to the token url', function (?string $refreshUrl, string $expectedRefreshTarget): void {
    $client = new MockTokenApiClient();
    $client->enqueueResponse(new ApiHttpResponse(200, (string) json_encode([
        'access_token' => 'pw-token-1',
        'refresh_token' => 'refresh-1',
        'expires_in' => 0,
    ]), ['Content-Type' => 'application/json']));
    $client->enqueueResponse(new ApiHttpResponse(200, (string) json_encode([
        'access_token' => 'pw-token-2',
        'expires_in' => 3600,
    ]), ['Content-Type' => 'application/json']));

    $authenticator = new OAuth2PasswordAuthenticator(
        'https://api.example.com',
        'my-client-id',
        'my-client-secret',
        'https://auth.example.com/token',
        'testuser',
        'testpass',
        [],
        $refreshUrl
    );
    $authenticator->setApiClient($client);

    $authenticator->getAuthHeaders();
    $authenticator->getAuthHeaders();

    expect($client->capturedRequests)->toHaveCount(2);
    expect($client->capturedRequests[0]['url'])->toBe('https://auth.example.com/token');
    expect($client->capturedRequests[0]['body'] ?? '')->toContain('grant_type=password');
    expect($client->capturedRequests[1]['url'])->toBe($expectedRefreshTarget);
    expect($client->capturedRequests[1]['body'] ?? '')->toContain('grant_type=refresh_token');
})->with([
    'distinct refresh url' => ['https://auth.example.com/refresh', 'https://auth.example.com/refresh'],
    'no refresh url' => [null, 'https://auth.example.com/token'],
]);

test('password basic auth keeps only the unreserved characters literal', function (): void {
    /* R8-10: exactly '-._~' stay literal; '*', '!', the quote and the
     * parentheses are percent-encoded in the Basic client credentials. */
    $client = new MockTokenApiClient();
    $client->enqueueResponse(new ApiHttpResponse(200, (string) json_encode([
        'access_token' => 'at',
        'expires_in' => 3600,
    ]), ['Content-Type' => 'application/json']));

    $authenticator = new OAuth2PasswordAuthenticator(
        'https://api.example.com',
        "id-._~*!'()",
        "sec-._~*!'()",
        'https://auth.example.com/token',
        'testuser',
        'testpass',
        [],
        null,
        ClientAuthMethod::Basic
    );
    $authenticator->setApiClient($client);

    $authenticator->getAuthHeaders();

    $authHeader = $client->capturedRequests[0]['headers']['Authorization'] ?? '';
    expect($authHeader)->toStartWith('Basic ');
    expect(base64_decode(substr($authHeader, strlen('Basic '))))
        ->toBe('id-._~%2A%21%27%28%29:sec-._~%2A%21%27%28%29');
});

